package com.autojobapply.discovery;
import com.autojobapply.config.Config; import com.autojobapply.matching.JobMatcher; import com.autojobapply.model.*; import com.autojobapply.tracking.ApplicationTracker; import java.util.*;
public final class GreenhousePipelineService { private final GreenhouseCompanyDiscoveryService companies;private final GreenhouseJobDiscoveryService jobs;private final ApplicationTracker tracker;private final JobMatcher matcher;private final Config config; public GreenhousePipelineService(GreenhouseCompanyDiscoveryService c,GreenhouseJobDiscoveryService j,ApplicationTracker t,JobMatcher m,Config x){companies=c;jobs=j;tracker=t;matcher=m;config=x;}
 public List<ScoredJob> run()throws Exception{List<ScoredJob> out=new ArrayList<>();for(GreenhouseCompanyDiscoveryService.Board b:companies.discover().stream().limit(50).toList()){boolean valid=companies.validate(b);tracker.saveEmployer(b.token(),b.company(),b.boardUrl(),b.apiUrl(),b.source(),valid);if(!valid)continue;for(Job job:jobs.retrieve(b)){tracker.saveGreenhouseJob(b.token(),job);if(tracker.isKnown(job))continue;ScoredJob s=matcher.score(job);tracker.record(s,s.eligible()?ApplicationStatus.MATCHED:ApplicationStatus.SKIPPED,null);if(s.eligible()){tracker.enqueue(b.token(),s);out.add(s);}}}return out;}}
